package com.fitbite.security;
import com.fitbite.repository.UserRepository; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.stream.*;
@Service public class CustomUserDetailsService implements UserDetailsService { private final UserRepository repo; public CustomUserDetailsService(UserRepository repo){this.repo=repo;} public UserDetails loadUserByUsername(String email)throws UsernameNotFoundException{return repo.findByEmailIgnoreCase(email).map(u->User.withUsername(u.getEmail()).password(u.getPassword()).authorities(u.getRoles().stream().map(r->new SimpleGrantedAuthority("ROLE_"+r.getName())).toList()).build()).orElseThrow(()->new UsernameNotFoundException("User not found"));}}
